const OB_FIELD_TYPES = ['text','textarea','email','phone','number','amount','date','select','multiselect','radio','checkbox','country','multicountry','file','consent','info'];
const obLabel = (ru,en) => ({ru,en});
const obField = (id,ru,en,type='text',required=true,options=[]) => ({id,label:obLabel(ru,en),type,required,options});
const obStep = (id,ru,en,fields=[],type='form') => ({id,title:obLabel(ru,en),type,layout:'one-column',visibleIf:null,fields});
const obName = obj => typeof obj==='string' ? obj : obj?.[I18N.language] || obj?.en || obj?.ru || '';
const deepCopy = obj => JSON.parse(JSON.stringify(obj));

function normalizeOnboardingSchema(raw) {
  const source=raw?.schema||raw;
  if(!source||typeof source!=='object'||Array.isArray(source))throw new Error(L('Нужен JSON-объект формы.','A form JSON object is required.'));
  const label=value=>typeof value==='string'?obLabel(value,value):value;
  return {...source,id:source.id||source.slug,name:label(source.name),steps:Array.isArray(source.steps)?source.steps.map(s=>({...s,title:label(s.title),type:s.type||'form',layout:s.layout||'one-column',visibleIf:s.visibleIf??null,fields:Array.isArray(s.fields)?s.fields.map(f=>({...f,type:f.type||f.kind,label:label(f.label),required:f.required??!!f.validators?.some(v=>v.kind==='required'),sourceOptions:!Array.isArray(f.options)&&f.options?.kind!=='static'?f.options:undefined,options:(Array.isArray(f.options)?f.options:f.options?.items||[]).map(o=>({...o,label:label(o.label)}))})):s.fields})):source.steps};
}
function onboardingSchema(form) {
  const source={id:form.id,slug:form.slug||form.id,name:form.name.en,version:form.version,locales:form.locales||['en','ru'],defaultLocale:form.defaultLocale||'en',start:form.start||form.steps[0]?.id,steps:form.steps.map(s=>({...s,fields:s.fields.map(f=>{const out={...f,kind:f.type,validators:[...(f.validators||[]).filter(v=>v.kind!=='required'),...(f.required?[{kind:'required'}]:[])]};if(f.options?.length)out.options={kind:'static',items:f.options};else if(f.sourceOptions)out.options=f.sourceOptions;else delete out.options;delete out.type;delete out.required;delete out.sourceOptions;return out})}))};
  if(form.edges)source.edges=deepCopy(form.edges);if(form.kyc)source.kyc=deepCopy(form.kyc);return source;
}

