function moduleDefaults() {return {paymentTab:'transfers',logStatus:'all',logDirection:'all',logQuery:'',logPayment:'',transactionType:'all',transactionStatus:'all',transactionQuery:'',cardQuery:'',onboardingTab:'forms',onboardingStatus:'all',onboardingQuery:'',submissionTab:'submissions',flowPhase:'all',flowStatus:'all',communicationChannel:'all',communicationStatus:'all',editor:null,levelEditor:null,moduleForm:null};}
function moduleTabs(items,current,attribute) {return `<div class="module-tabs" role="group">${items.map(([id,ru,en])=>`<button type="button" ${attribute}="${id}" aria-pressed="${id===current}" class="${id===current?'active':''}">${esc(L(ru,en))}</button>`).join('')}</div>`;}
function paymentTabs(){return moduleTabs([['transfers','Переводы','Transfers'],['logs','Логи платежей','Payment logs']],ui.paymentTab,'data-payment-tab');}
function moduleSelect(id,items,value,label){return `<label class="filter-control"><span>${esc(label)}</span><select id="${id}" class="select">${items.map(([key,name])=>`<option value="${esc(key)}" ${key===value?'selected':''}>${esc(name)}</option>`).join('')}</select></label>`;}
function moduleQuery(id,value,placeholder){return `<label class="module-search">${icon('search')}<span class="sr-only">${esc(placeholder)}</span><input id="${id}" type="search" value="${esc(value)}" placeholder="${esc(placeholder)}" autocomplete="off"></label>`;}
function moduleMatches(query,...values){const q=query.trim().toLocaleLowerCase();return !q||values.some(v=>String(v??'').toLocaleLowerCase().includes(q)||I18N.text(v,'en').toLocaleLowerCase().includes(q));}
function demoClientCell(id){const c=client(id);return `<button class="cell-title" data-action="client" data-id="${esc(id)}">${esc(I18N.text(c.name))}</button><span class="cell-sub mono">${esc(c.code)}</span>`;}
function moduleButton(action,id,ru,en,symbol='arrow',style=''){return `<button type="button" class="button compact ${style}" data-module-action="${action}" data-id="${esc(id??'')}">${esc(L(ru,en))}${symbol?icon(symbol):''}</button>`;}
function saveModule(){return save();}
function renderKeepFocus(){const active=document.activeElement,id=active?.id,start=active?.selectionStart,end=active?.selectionEnd;render();const next=id&&$(id);if(next){next.focus({preventScroll:true});if(typeof start==='number'&&next.setSelectionRange)try{next.setSelectionRange(start,end)}catch{}}}

